diff --git a/packages/workflow/src/expressions/native-evaluation/evaluator.ts b/packages/workflow/src/expressions/native-evaluation/evaluator.ts
index 6883c56c6..414ed0bc0 100644
--- a/packages/workflow/src/expressions/native-evaluation/evaluator.ts
+++ b/packages/workflow/src/expressions/native-evaluation/evaluator.ts
@@ -286,6 +286,9 @@ function flatSize(array: unknown[], depth: number): number {
  */
 const STRINGIFIES_ELEMENTS = new Set(['join', 'toSorted']);

+/** Array methods that compare each element with the argument. */
+const COMPARES_ELEMENTS = new Set(['includes', 'indexOf', 'lastIndexOf']);
+
 /**
  * Hands off to the engine unless every element is a primitive. O(n) over a
  * receiver the size cap already limits, and runs before anything is
@@ -389,6 +392,13 @@ function evalCall(node: Extract<SimpleNode, { kind: 'call' }>, env: Env): unknow
 	if (isArray(receiver)) {
 		if (STRINGIFIES_ELEMENTS.has(node.method)) assertPrimitiveElements(receiver);
 		if (node.method === 'concat') assertConcatWeight(receiver, args);
+		if (COMPARES_ELEMENTS.has(node.method)) {
+			// Each comparison can walk a whole string element, so the element
+			// count undercounts: charge the receiver's content.
+			const weight = contentWeight(receiver, MAX_RESULT_LENGTH);
+			if (weight > MAX_RESULT_LENGTH) throw new EngineFallbackError();
+			env.charge(weight);
+		}
 	}
 	env.charge(preflightSize(receiver, node.method, args));

diff --git a/packages/workflow/test/native-evaluation-parity.test.ts b/packages/workflow/test/native-evaluation-parity.test.ts
index 40cb5da55..859190013 100644
--- a/packages/workflow/test/native-evaluation-parity.test.ts
+++ b/packages/workflow/test/native-evaluation-parity.test.ts
@@ -642,6 +642,29 @@ describe('Expression - fast native evaluation parity', () => {
 			).toEqual({ handled: false });
 		});

+		// Comparing array methods walk string elements, so the receiver's content
+		// is charged, not its element count.
+		test('array includes/indexOf/lastIndexOf are charged by element content', () => {
+			const half = MAX_RESULT_LENGTH / 2 - 10;
+			const longs = [
+				'a'.repeat(half / 2),
+				'b'.repeat(half / 2),
+			];
+			const visits = Math.ceil(MAX_WORK / half);
+			for (const method of ['includes', 'indexOf', 'lastIndexOf']) {
+				expect(
+					nativeOn(`{{ $json.few.some(n => $json.longs.${method}(n) === 5) }}`, {
+						$json: { few: new Array<string>(visits + 2).fill('y'), longs },
+					}),
+				).toEqual({ handled: false });
+				expect(
+					nativeOn(`{{ $json.few.some(n => $json.longs.${method}(n) === 5) }}`, {
+						$json: { few: ['y', 'y'], longs },
+					}),
+				).toMatchObject({ handled: true });
+			}
+		});
+
 		// A `$parameter` read resolves a nested expression in its own evaluation,
 		// with its own budgets. Read once per evaluation (as the vm bridge does),
 		// a body cannot resolve it once per element.
